const dialog=document.querySelector('#preview'),content=document.querySelector('#preview-content');let lastFocus;
function openDialog(){lastFocus=document.activeElement;dialog.showModal();document.body.classList.add('modal-open')}
document.querySelector('#watch-demo').addEventListener('click',()=>{content.innerHTML='<h2 style="margin:0 0 20px">FilmWizard in action.</h2><iframe src="https://www.loom.com/embed/a5f75b4b78f8497ab40e7bd4de80740c?autoplay=0&hide_owner=true&hide_share=true" title="Film Wizard official introduction" allow="autoplay; fullscreen; picture-in-picture" allowfullscreen></iframe><p>Official FilmWizard introduction. <a href="https://www.loom.com/share/a5f75b4b78f8497ab40e7bd4de80740c" target="_blank" rel="noopener">Open on Loom ↗</a></p>';openDialog()});
document.querySelector('.close').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog){const r=dialog.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)dialog.close()}});dialog.addEventListener('close',()=>{content.replaceChildren();document.body.classList.remove('modal-open');lastFocus?.focus()});const menu=document.querySelector('.menu-toggle');menu.addEventListener('click',()=>{const open=document.querySelector('nav').classList.toggle('open');menu.setAttribute('aria-expanded',String(open))});document.querySelectorAll('nav a').forEach(a=>a.addEventListener('click',()=>{document.querySelector('nav').classList.remove('open');menu.setAttribute('aria-expanded','false')}));
let heroVisible=true,offerVisible=false;const sticky=document.querySelector('.sticky-offer');function updateSticky(){sticky.hidden=heroVisible||offerVisible}new IntersectionObserver(e=>{heroVisible=e[0].isIntersecting;updateSticky()}).observe(document.querySelector('.hero'));new IntersectionObserver(e=>{offerVisible=e[0].isIntersecting;updateSticky()},{threshold:.2}).observe(document.querySelector('.price-card'));
// Product walkthrough is an illustration, not a live generator or editor.
const studioBody=document.querySelector('.studio-body'),studioTabs=[...document.querySelectorAll('[data-studio]')],studioPlay=document.querySelector('#studio-play'),studioTyped=document.querySelector('#studio-typed');
const studioSteps={generate:{label:'01 / GENERATE',heading:'Your idea becomes the raw material.',copy:'Create visuals with AI and use Wizard Agent to develop your idea into a video workflow.'},edit:{label:'02 / EDIT',heading:'Make the cut. Make it yours.',copy:'Arrange clips, work with audio and add text on the built-in timeline. Shape the story in the same studio.'},publish:{label:'03 / PUBLISH',heading:'Finish the video. Keep the momentum.',copy:'Take your finished content to social, then reuse your assets and workflow for the next idea.'}};
const motionPreference=matchMedia('(prefers-reduced-motion: reduce)');let studioElapsed=0,studioLast=0,studioPlaying=!motionPreference.matches,studioVisible=false,studioCurrent='';
function setStudioView(name){if(studioCurrent===name)return;studioCurrent=name;studioBody.dataset.view=name;studioTabs.forEach(b=>{const yes=b.dataset.studio===name;b.setAttribute('aria-selected',String(yes));b.tabIndex=yes?0:-1});document.querySelector('#studio-panel').setAttribute('aria-labelledby','studio-'+name);document.querySelectorAll('.studio-pane').forEach(p=>p.hidden=!p.classList.contains(name+'-pane'));const step=studioSteps[name];document.querySelector('#studio-step-label').textContent=step.label;document.querySelector('#studio-step-heading').textContent=step.heading;document.querySelector('#studio-step-copy').textContent=step.copy}
function syncStudioControl(){studioPlay.textContent=studioPlaying?'Ⅱ Pause walkthrough':'▶ Play walkthrough';studioPlay.setAttribute('aria-label',studioPlaying?'Pause studio walkthrough':'Play studio walkthrough');studioBody.classList.toggle('walkthrough-paused',!studioPlaying)}
function paintStudio(){const t=studioElapsed%18000;const view=t<6000?'generate':t<12500?'edit':'publish';setStudioView(view);const prompt='Create a cinematic product video for my brand.';studioTyped.textContent=prompt.slice(0,Math.floor(t/48));studioBody.dataset.ready=String(t>2300);document.querySelector('#generation-status').textContent=t<2300?'Describe your idea. Set the direction.':'Your visuals, ready for the timeline.'}
function selectStudio(name){studioPlaying=false;studioElapsed={generate:3500,edit:6500,publish:13000}[name];paintStudio();syncStudioControl()}
studioTabs.forEach((b,i)=>{b.addEventListener('click',()=>selectStudio(b.dataset.studio));b.addEventListener('keydown',e=>{let n;if(e.key==='ArrowRight')n=(i+1)%studioTabs.length;if(e.key==='ArrowLeft')n=(i+studioTabs.length-1)%studioTabs.length;if(e.key==='Home')n=0;if(e.key==='End')n=studioTabs.length-1;if(n!==undefined){e.preventDefault();studioTabs[n].focus();selectStudio(studioTabs[n].dataset.studio)}})});
studioPlay.addEventListener('click',()=>{studioPlaying=!studioPlaying;syncStudioControl()});new IntersectionObserver(e=>{studioVisible=e[0].isIntersecting},{threshold:.15}).observe(document.querySelector('.studio-app'));
function studioTick(now){if(studioLast&&studioPlaying&&studioVisible&&!document.hidden){studioElapsed+=Math.min(now-studioLast,100);paintStudio()}studioLast=now;requestAnimationFrame(studioTick)}
motionPreference.addEventListener('change',()=>{studioPlaying=!motionPreference.matches;if(motionPreference.matches)studioElapsed=3500;paintStudio();syncStudioControl()});if(motionPreference.matches)studioElapsed=3500;paintStudio();syncStudioControl();requestAnimationFrame(studioTick);
